statement:
There are `n` buildings in a row, numbered `1` to `n`, and you choose a height for each one. The heights must obey these rules:

- every height is a non-negative integer;
- building `1` has height `0`;
- two neighbouring buildings differ in height by at most `1`;
- each entry `restrictions[i] = [id_i, maxHeight_i]` caps building `id_i` at a height of at most `maxHeight_i`.

No building is listed in `restrictions` more than once, and building `1` is never listed. Among all valid choices of heights, return the largest height that the tallest building can reach.

validator:
function validate([n, restrictions]) {
  if (!Number.isInteger(n) || n < 2 || n > 1000000000) return 'n must be an integer from 2 to 10^9.';
  if (!Array.isArray(restrictions)) return 'restrictions must be a list of [id, maxHeight] pairs.';
  if (restrictions.length > Math.min(n - 1, 100000)) return 'There can be at most min(n - 1, 10^5) restrictions.';
  const seen = new Set();
  for (const pair of restrictions) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each restriction is a pair [id, maxHeight].';
    const [id, height] = pair;
    if (!Number.isInteger(id) || id < 2 || id > n) return 'Each id must be between 2 and n.';
    if (!Number.isInteger(height) || height < 0 || height > 1000000000) return 'Each maxHeight must be between 0 and 10^9.';
    if (seen.has(id)) return 'Each building may be restricted only once.';
    seen.add(id);
  }
  return null;
}

