function maxBuilding(n, restrictions) {
  const limits = restrictions.map(([id, height]) => [id, height]);
  limits.push([1, 0]);
  limits.sort((a, b) => a[0] - b[0]);
  if (limits[limits.length - 1][0] !== n) {
    limits.push([n, n - 1]);
  }

  for (let i = 1; i < limits.length; i++) {
    const gap = limits[i][0] - limits[i - 1][0];
    limits[i][1] = Math.min(limits[i][1], limits[i - 1][1] + gap);
  }
  for (let i = limits.length - 2; i >= 0; i--) {
    const gap = limits[i + 1][0] - limits[i][0];
    limits[i][1] = Math.min(limits[i][1], limits[i + 1][1] + gap);
  }

  let best = 0;
  for (let i = 1; i < limits.length; i++) {
    const [leftId, leftHeight] = limits[i - 1];
    const [rightId, rightHeight] = limits[i];
    const peak = Math.floor((leftHeight + rightHeight + rightId - leftId) / 2);
    best = Math.max(best, peak);
  }
  return best;
}

brute:
function maxBuilding(n, restrictions) {
  // The tallest a building b can be is min(cap + |b - id|) over every cap, and taking
  // that value at every building gives a valid row. That function is made of slopes of
  // +1 and -1, so its maximum sits at an end, a capped building, or where a rising line
  // from one cap meets a falling line from another: only those buildings are checked.
  const caps = [[1, 0], ...restrictions];
  const heightAt = (b) => {
    let height = Infinity;
    for (const [id, cap] of caps) height = Math.min(height, cap + Math.abs(b - id));
    return height;
  };
  const candidates = [1, n];
  for (const [id] of caps) candidates.push(id);
  for (const [idA, capA] of caps) {
    for (const [idB, capB] of caps) {
      const meet = (capB + idB - capA + idA) / 2;
      candidates.push(Math.floor(meet), Math.ceil(meet));
    }
  }
  let answer = 0;
  for (const b of candidates) {
    if (b >= 1 && b <= n) answer = Math.max(answer, heightAt(b));
  }
  return answer;
}

generator:
function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(2, 25);
    const count = int(0, Math.min(n - 1, 8));
    const ids = [];
    for (let id = 2; id <= n; id++) ids.push(id);
    for (let i = ids.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [ids[i], ids[j]] = [ids[j], ids[i]];
    }
    const top = rand() < 0.5 ? 4 : n + 3;
    return [n, ids.slice(0, count).map(id => [id, int(0, top)])];
  }
  const n = rand() < 0.3 ? 1000000000 : int(2000, 1000000000);
  const count = int(1000, 2000);
  const top = rand() < 0.5 ? 1000000000 : int(0, 1000000);
  const used = new Set();
  const restrictions = [];
  while (restrictions.length < count) {
    const id = int(2, n);
    if (used.has(id)) continue;
    used.add(id);
    restrictions.push([id, int(0, top)]);
  }
  return [n, restrictions];
}
